/* ===== EXPECTED RESPONSE (OK 200) =====
{
  "success": true,
  "message": "Logged in successfully.",
  "data": {
    "token": "eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9...",
    "refreshToken": "3f8a1c2e9b4d5f6a7c8e9d0b1a2c3d4e5f6a7b8c9d0e1f2a",
    "user": {
      "id": "a1b2c3d4-e5f6-7890-abcd-ef1234567890",
      "fullName": "Super Admin",
      "email": "superadmin@farmerapp.com",
      "phone": null,
      "role": "super_admin"
    }
  }
}
===== END EXPECTED RESPONSE ===== */

requests.testScript:
pw.test("Status is 200", () => { pw.expect(pw.response.status).toBe(200); });
pw.test("success is true", () => { pw.expect(pw.response.body.success).toBe(true); });
const d = pw.response.body.data;
if (d && d.token) pw.env.set('token', d.token);
if (d && d.refreshToken) pw.env.set('refreshToken', d.refreshToken);
if (d && d.user && d.user.id) { pw.env.set('userId', d.user.id); if (d.user.role === 'farmer') pw.env.set('farmerId', d.user.id); if (d.user.role === 'assessor') pw.env.set('assessorId', d.user.id); }

Success example.body:
